fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let output_len = m.max(n);
    
    let mut result_a = Vec::with_capacity(output_len);
    let mut result_b = Vec::with_capacity(output_len);
    
    if m == n {
        // Both arrays have same length
        result_a.extend_from_slice(&a);
        result_b.extend_from_slice(&b);
    } else if m == 1 {
        // First array has length 1, broadcast it
        result_a.extend(std::iter::repeat(a[0]).take(output_len));
        result_b.extend_from_slice(&b);
    } else if n == 1 {
        // Second array has length 1, broadcast it
        result_a.extend_from_slice(&a);
        result_b.extend(std::iter::repeat(b[0]).take(output_len));
    } else {
        // This case shouldn't happen per problem assumptions (arrays are compatible)
        // But we handle it defensively
        panic!("Arrays are not compatible for broadcasting");
    }
    
    (result_a, result_b)
}